engine.onAlarm:
a = bsf.lookupBean("alarm");
try {
   url = new java.net.URL("http://REPLACE_HOST:9000/opennms/alarm");
   conn = url.openConnection();
   conn.setRequestMethod("POST");
   conn.setRequestProperty("Content-Type", "application/json");
   conn.setConnectTimeout(3000);
   conn.setReadTimeout(3000);
   conn.setDoOutput(true);

   msg = a.getLogMsg();
   if (msg == null) msg = "";
   msg = msg.replace("\\", "\\\\").replace("\"", "'");

   label = a.getNodeLabel();
   if (label == null) label = "";

   json = "{"
      + "\"alarmId\":" + a.getId() + ","
      + "\"uei\":\"" + a.getUei() + "\","
      + "\"nodeLabel\":\"" + label + "\","
      + "\"severity\":\"" + a.getSeverity() + "\","
      + "\"logMsg\":\"" + msg + "\""
      + "}";

   os = conn.getOutputStream();
   os.write(json.getBytes("UTF-8"));
   os.flush();
   os.close();

   log.info("webhook forwarder: posted alarm " + a.getId() + " -> HTTP " + conn.getResponseCode());
} catch (Exception e) {
   log.error("webhook forwarder: failed to post alarm " + a.getId() + ": " + e);
}
